import re, pathlib

s = open('scripts/chain-walk.sh').read()
order = re.search(r'\nORDER=\((.*?)\n\)\n', s, re.S).group(1).split()
WIDE = re.compile(r'const (?:TARGET_RELATIVE_PATH|targetRelativePath|target) =\s*\n?\s*"([^"\n]+)"')
REF = re.compile(r'"(ratchets/[^"\n]+)"')


def body(name):
    return pathlib.Path('crates/oracle/' + name + '.mjs').read_text()


def graph(names):
    prod = dict()
    for i, n in enumerate(names):
        for t in WIDE.findall(body(n)):
            if t.startswith('ratchets/'):
                prod[t] = (n, i)
    inv = []
    for i, n in enumerate(names):
        own = set(a for a, v in prod.items() if v[0] == n)
        for a in sorted(set(REF.findall(body(n)))):
            if a in own:
                continue
            if a in prod:
                pn, pi = prod[a]
                if pn != n and pi > i:
                    inv.append((n, i, a, pn, pi))
    return prod, inv


prod, inv = graph(order)
print('CURRENT ORDER + widened regex: %d inversions' % len(inv))
for r in inv:
    print('   %s(%d) -> %s produced by %s(%d)' % r)

moved = ('h2-7b-qualification', 'h2-7c-qualification', 'h2-7de-qualification')
new = [n for n in order if n not in moved]
k = new.index('h2-5g-profile')
new[k:k] = list(moved)
prod2, inv2 = graph(new)
print('PROPOSED ORDER: %d inversions' % len(inv2))
for r in inv2:
    print('   %s(%d) -> %s produced by %s(%d)' % r)

posn = dict()
for i, n in enumerate(new):
    posn[n] = i
print('refs of moved rungs under proposed order:')
for n in moved:
    for a in sorted(set(REF.findall(body(n)))):
        v = prod2.get(a)
        pn = v[0] if v else None
        pi = v[1] if v else None
        print('   %s(%d) <- %s :: %s(%s)' % (n, posn[n], a, pn, pi))
print('newly discovered producers by widening:')
base = re.compile(r'const (?:TARGET_RELATIVE_PATH|targetRelativePath) =\s*\n?\s*"([^"\n]+)"')
for n in order:
    wide = set(t for t in WIDE.findall(body(n)) if t.startswith('ratchets/'))
    narrow = set(t for t in base.findall(body(n)) if t.startswith('ratchets/'))
    if wide - narrow:
        print('   %s: %s' % (n, sorted(wide - narrow)))
